import{_ as e,o as a,c as i,a0 as l}from"./chunks/framework.DQOulFGV.js";const I="data:image/svg+xml;base64,",s="data:image/svg+xml;base64,",m=JSON.parse('{"title":"第4章 AOF 与混合持久化","description":"","frontmatter":{},"headers":[],"relativePath":"redis/02-standalone-core/chapter-04-aof.md","filePath":"redis/02-standalone-core/chapter-04-aof.md"}'),d={name:"redis/02-standalone-core/chapter-04-aof.md"};function n(g,t,h,o,c,p){return a(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="第4章-aof-与混合持久化" tabindex="-1">第4章 AOF 与混合持久化 <a class="header-anchor" href="#第4章-aof-与混合持久化" aria-label="Permalink to &quot;第4章 AOF 与混合持久化&quot;">​</a></h1><blockquote><p>AOF（Append Only File）通过记录每一条写命令来实现持久化，比 RDB 更接近「实时」。本章讲解 AOF 的原理、重写机制，以及 RDB + AOF 的混合持久化方案。</p></blockquote><hr><h2 id="_4-1-aof-原理" tabindex="-1">4.1 AOF 原理 <a class="header-anchor" href="#_4-1-aof-原理" aria-label="Permalink to &quot;4.1 AOF 原理&quot;">​</a></h2><p>AOF 记录服务器收到的每一条写命令，重启时按顺序重新执行这些命令来重建数据。</p><p><img src="'+I+`" alt="AOF 追加流程"></p><h3 id="三种刷盘策略" tabindex="-1">三种刷盘策略 <a class="header-anchor" href="#三种刷盘策略" aria-label="Permalink to &quot;三种刷盘策略&quot;">​</a></h3><p>刷盘策略由 <code>appendfsync</code> 配置决定，权衡「性能」与「数据安全」：</p><table tabindex="0"><thead><tr><th style="text-align:left;">策略</th><th style="text-align:left;">配置值</th><th style="text-align:left;">刷盘时机</th><th style="text-align:left;">数据安全</th><th style="text-align:left;">性能</th></tr></thead><tbody><tr><td style="text-align:left;">每次刷盘</td><td style="text-align:left;"><code>always</code></td><td style="text-align:left;">每条命令都同步到磁盘</td><td style="text-align:left;">最高，最多丢 1 条</td><td style="text-align:left;">最差</td></tr><tr><td style="text-align:left;">每秒刷盘</td><td style="text-align:left;"><code>everysec</code></td><td style="text-align:left;">每秒同步一次</td><td style="text-align:left;">较高，最多丢 1 秒</td><td style="text-align:left;">较好</td></tr><tr><td style="text-align:left;">不主动刷盘</td><td style="text-align:left;"><code>no</code></td><td style="text-align:left;">交给操作系统</td><td style="text-align:left;">最差，丢多少不可控</td><td style="text-align:left;">最好</td></tr></tbody></table><blockquote><p>生产环境默认推荐 <code>everysec</code>：性能损失小，最多丢失 1 秒数据，是安全与性能的最佳平衡点。</p></blockquote><h3 id="数据还原流程" tabindex="-1">数据还原流程 <a class="header-anchor" href="#数据还原流程" aria-label="Permalink to &quot;数据还原流程&quot;">​</a></h3><p>重启时 Redis 按顺序重放 AOF 文件中的命令：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AOF 文件：SET a 1 → SET b 2 → INCR a → DEL b</span></span>
<span class="line"><span>重放结果：a=2，b 不存在（按命令顺序执行）</span></span></code></pre></div><hr><h2 id="_4-2-aof-重写" tabindex="-1">4.2 AOF 重写 <a class="header-anchor" href="#_4-2-aof-重写" aria-label="Permalink to &quot;4.2 AOF 重写&quot;">​</a></h2><p>AOF 文件会随着写命令累积越来越大，需要定期「重写」压缩。</p><h3 id="为什么要重写" tabindex="-1">为什么要重写 <a class="header-anchor" href="#为什么要重写" aria-label="Permalink to &quot;为什么要重写&quot;">​</a></h3><p>很多命令是冗余的（先 SET 再 DEL，最终这个 key 不存在），重写可以把「过程」压缩成「结果」，大幅减小文件体积：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>重写前：SET a 1; SET a 2; SET a 3; INCR a</span></span>
<span class="line"><span>重写后：SET a 4        ← 只保留最终结果</span></span></code></pre></div><h3 id="重写原理" tabindex="-1">重写原理 <a class="header-anchor" href="#重写原理" aria-label="Permalink to &quot;重写原理&quot;">​</a></h3><p>重写不是分析旧 AOF 文件，而是<strong>读取当前内存数据</strong>，生成一个只包含最终状态的最小命令集。</p><p><img src="`+s+`" alt="AOF 重写流程"></p><p>关键点：</p><table tabindex="0"><thead><tr><th style="text-align:left;">环节</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">子进程重写</td><td style="text-align:left;">fork 子进程后台生成新文件，主进程不阻塞</td></tr><tr><td style="text-align:left;">增量缓冲</td><td style="text-align:left;">重写期间的新写命令记入缓冲区，最后追加到新文件</td></tr><tr><td style="text-align:left;">原子替换</td><td style="text-align:left;">新文件写完后原子替换旧文件</td></tr></tbody></table><h3 id="触发重写" tabindex="-1">触发重写 <a class="header-anchor" href="#触发重写" aria-label="Permalink to &quot;触发重写&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">auto-aof-rewrite-percentage</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # AOF 增长超过 100% 触发</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">auto-aof-rewrite-min-size</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 64mb</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 最小触发体积</span></span></code></pre></div><hr><h2 id="_4-3-混合持久化" tabindex="-1">4.3 混合持久化 <a class="header-anchor" href="#_4-3-混合持久化" aria-label="Permalink to &quot;4.3 混合持久化&quot;">​</a></h2><p>Redis 4.0 引入混合持久化：AOF 重写时，文件开头是 RDB 快照，之后追加增量 AOF 命令。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>混合持久化文件结构</span></span>
<span class="line"><span>┌─────────────────┬──────────────────────┐</span></span>
<span class="line"><span>│  RDB 快照头部    │  后续增量 AOF 命令     │</span></span>
<span class="line"><span>│  （快速恢复）     │  （实时性）           │</span></span>
<span class="line"><span>└─────────────────┴──────────────────────┘</span></span></code></pre></div><p>混合持久化结合了两者优势：</p><table tabindex="0"><thead><tr><th style="text-align:left;">特性</th><th style="text-align:left;">RDB</th><th style="text-align:left;">AOF</th><th style="text-align:left;">混合</th></tr></thead><tbody><tr><td style="text-align:left;">恢复速度</td><td style="text-align:left;">快</td><td style="text-align:left;">慢（重放命令）</td><td style="text-align:left;">快（先加载 RDB）</td></tr><tr><td style="text-align:left;">数据安全</td><td style="text-align:left;">丢快照间隔</td><td style="text-align:left;">最多丢 1 秒</td><td style="text-align:left;">最多丢 1 秒</td></tr><tr><td style="text-align:left;">文件体积</td><td style="text-align:left;">小</td><td style="text-align:left;">大</td><td style="text-align:left;">中等</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aof-use-rdb-preamble</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yes</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 开启混合持久化（4.0+ 默认）</span></span></code></pre></div><hr><h2 id="_4-4-持久化选型与坑" tabindex="-1">4.4 持久化选型与坑 <a class="header-anchor" href="#_4-4-持久化选型与坑" aria-label="Permalink to &quot;4.4 持久化选型与坑&quot;">​</a></h2><h3 id="选型建议" tabindex="-1">选型建议 <a class="header-anchor" href="#选型建议" aria-label="Permalink to &quot;选型建议&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">场景</th><th style="text-align:left;">推荐方案</th></tr></thead><tbody><tr><td style="text-align:left;">缓存（可丢数据）</td><td style="text-align:left;">不开启持久化</td></tr><tr><td style="text-align:left;">数据重要、可容忍少量丢失</td><td style="text-align:left;">混合持久化（<code>everysec</code>）</td></tr><tr><td style="text-align:left;">数据极重要、不能丢</td><td style="text-align:left;">AOF <code>always</code> + 从库</td></tr></tbody></table><h3 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">坑</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">主节点不开启持久化</td><td style="text-align:left;">主从切换时新主无数据，导致数据丢失</td></tr><tr><td style="text-align:left;">从节点开启持久化代替主节点</td><td style="text-align:left;">主节点宕机数据全丢，从节点可能也没同步到</td></tr><tr><td style="text-align:left;">恢复优先级混乱</td><td style="text-align:left;">同时存在 RDB 和 AOF 时，Redis 优先用 AOF 恢复（数据更新）</td></tr><tr><td style="text-align:left;">fsync 设置过严</td><td style="text-align:left;"><code>always</code> 严重拖慢性能，非强一致需求别用</td></tr></tbody></table><blockquote><p>一个高频故障：主节点关闭持久化、依赖从节点持久化，主节点宕机后哨兵把从节点提升为主，但数据其实不全。正确做法是<strong>主节点必须开启持久化</strong>。</p></blockquote>`,40)])])}const y=e(d,[["render",n]]);export{m as __pageData,y as default};
